.auth-page { min-height:780px; max-width:1180px; margin:0 auto; padding:76px 28px 110px; display:grid; grid-template-columns:minmax(300px,.9fr) minmax(400px,1fr); gap:90px; align-items:center; }.auth-copy h1 { font:600 clamp(46px,5vw,72px)/.98 'Space Grotesk'; letter-spacing:-.055em; margin:22px 0; }.auth-copy h1 em { color:var(--orange); font-style:normal; }.auth-copy > p { max-width:500px; color:#b1b6af; font-size:16px; line-height:1.65; }.benefit-list { margin-top:36px; display:grid; gap:18px; }.benefit-list > div { display:grid; grid-template-columns:28px 1fr; column-gap:10px; }.benefit-list span { grid-row:span 2; width:24px; height:24px; display:grid; place-items:center; border:1px solid rgba(243,107,33,.45); border-radius:50%; color:var(--orange); }.benefit-list strong { font-size:13px; color:#eee; }.benefit-list small { color:#737a73; font-size:11px; margin-top:4px; line-height:1.4; }.auth-card { background:linear-gradient(135deg,rgba(243,107,33,.08),transparent 24%),#121512; border:1px solid rgba(243,107,33,.35); border-radius:7px; padding:30px; box-shadow:0 22px 70px rgba(0,0,0,.28); }.auth-card-top { display:flex; gap:13px; align-items:flex-start; }.auth-mark { width:36px; height:36px; display:grid; place-items:center; background:rgba(243,107,33,.15); color:var(--orange); border:1px solid rgba(243,107,33,.4); border-radius:5px; }.auth-card h2 { font:600 28px 'Space Grotesk'; margin:7px 0 0; }.social-row { display:grid; grid-template-columns:1fr 110px; gap:8px; margin-top:28px; }.social-button { min-height:44px; display:flex; justify-content:center; align-items:center; gap:8px; background:#0d0f0d; border:1px solid rgba(255,255,255,.12); color:#e9e8e3; border-radius:5px; font-size:12px; }.social-button:hover { border-color:rgba(243,107,33,.55); }.google-g { font-weight:700; color:#4285f4; font-size:16px; }.auth-divider { display:flex; align-items:center; gap:10px; color:#616761; font-size:10px; margin:21px 0; }.auth-divider:before, .auth-divider:after { content:''; height:1px; flex:1; background:rgba(255,255,255,.1); }.auth-form { display:grid; gap:17px; }.field small { color:#666d66; font-size:10px; margin-left:5px; }.input-with-icon { position:relative; display:flex; align-items:center; }.input-with-icon > svg { position:absolute; left:12px; color:#6f766f; pointer-events:none; }.input-with-icon input { padding-left:36px; padding-right:38px; }.eye { position:absolute; right:9px; color:#737973; background:transparent; padding:5px; }.auth-submit { width:100%; margin-top:2px; }.spin { animation:spin 1s linear infinite; }@keyframes spin { to { transform:rotate(360deg); } }.auth-message { padding:11px 12px; border-radius:4px; font-size:11px; line-height:1.4; }.auth-message.error { color:#ffb2a1; background:rgba(172,54,29,.13); border:1px solid rgba(219,91,66,.3); }.auth-message.success { display:flex; gap:8px; color:#b7e4ba; background:rgba(53,128,61,.14); border:1px solid rgba(92,170,102,.3); }.auth-helpers { display:flex; justify-content:space-between; gap:10px; margin-top:15px; }.auth-helpers.single { justify-content:center; }.auth-helpers button, .magic-row button { color:var(--orange); background:transparent; font-size:11px; }.magic-row { display:flex; justify-content:center; margin-top:22px; padding-top:18px; border-top:1px solid rgba(255,255,255,.08); }.magic-row button { display:flex; align-items:center; gap:6px; }.guest-row { text-align:center; margin-top:18px; }.guest-row a { display:inline-flex; align-items:center; gap:7px; color:#9ca29b; font-size:11px; }.guest-row a:hover { color:#fff; }.auth-footnote { display:flex; justify-content:center; align-items:center; gap:6px; color:#626962; font-size:10px; margin-top:26px; }.auth-footnote svg { color:#7c9a80; }
@media (max-width: 900px) { .auth-page { grid-template-columns:1fr; gap:45px; max-width:620px; }.auth-copy { text-align:center; }.auth-copy > p { margin:0 auto; }.benefit-list { text-align:left; max-width:420px; margin-left:auto; margin-right:auto; } }
@media (max-width: 720px) { .saved-list { grid-template-columns:1fr; }.auth-page { padding:55px 20px 80px; }.auth-copy h1 { font-size:50px; }.auth-card { padding:22px 18px; }.social-row { grid-template-columns:1fr; }.auth-card-top .section-kicker span { display:none; }.auth-helpers { font-size:10px; } }

