color:#697069; font-size:10px; margin-top:22px; }.security-note svg { color:#82a487; }
@media (max-width:720px) { .account-page { padding:55px 20px 80px; }.account-grid { grid-template-columns:1fr; margin-top:40px; }.code-entry { grid-template-columns:1fr; }.code-entry .forge-button { width:100%; } }

.auth-message.notice { margin:14px 0 0; border-color:rgba(243,107,33,.26); background:rgba(243,107,33,.07); color:#c5a78f; font-size:11px; line-height:1.45; }

.admin-page { max-width: 1180px; margin: 0 auto; padding: 56px 28px 96px; }
