.nav-link:hover, .nav-link.active, .signin:hover, .signin.active { color: #fff; background: rgba(244,122,42,.11); }
.nav-link:hover::after, .nav-link.active::after { transform: scaleX(1); }
.unlock-button, .forge-button { min-height: 44px; border-radius: 5px; box-shadow: 0 8px 22px rgba(244,122,42,.12); transition: transform .18s cubic-bezier(.23,1,.32,1), filter .18s, box-shadow .18s; }
.unlock-button:hover, .forge-button:hover { filter: brightness(1.08); box-shadow: 0 10px 28px rgba(244,122,42,.2); }
button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible { outline: 2px solid var(--orange); outline-offset: 3px; }
.builder-hero { min-height: 400px; padding-top: 72px; padding-bottom: 62px; }
