.category, .library-card, .about-feature, .story-grid article, .faq-grid details, .contact-card, .settings-card, .auth-card, .form-card { background: linear-gradient(140deg, rgba(255,255,255,.025), transparent 45%), #151815; box-shadow: 0 10px 28px rgba(0,0,0,.12); }
