/* Library loading and recovery states */
.catalog-skeleton { align-items: stretch; }
.skeleton-card { pointer-events: none; overflow: hidden; }
.skeleton-line { position: relative; overflow: hidden; background: rgba(255,255,255,.08); border-radius: 3px; }
.skeleton-line::after { content: ''; position: absolute; inset: 0; transform: translateX(-100%); background: linear-gradient(90deg, transparent, rgba(243,107,33,.16), transparent); animation: catalog-shimmer 1.4s ease-in-out infinite; }
.skeleton-stamp { width: 76%; height: 10px; margin-bottom: 22px; }
