.skeleton-title { width: 88%; height: 25px; margin-bottom: 17px; }
.skeleton-copy { width: 92%; height: 11px; margin-bottom: 9px; }
.skeleton-copy.short { width: 64%; }
.skeleton-action { width: 92px; height: 28px; margin-top: auto; }
.catalog-error { border-color: rgba(243,107,33,.34); background: linear-gradient(135deg, rgba(243,107,33,.08), rgba(17,19,17,.92)); }
