.catalog-select { flex:0 0 270px; position:relative; display:flex; flex-direction:column; gap:6px; color:#858b84; font-size:10px; letter-spacing:.1em; text-transform:uppercase; }
.catalog-select select { width:100%; appearance:none; background:#0d0f0d; color:#e8e7e2; border:1px solid rgba(255,255,255,.12); border-radius:6px; padding:13px 36px 13px 13px; outline:none; font-size:13px; letter-spacing:0; text-transform:none; }
