import { afterEach, describe, expect, it, vi } from "vitest";
import { copyText } from "./copyText";

afterEach(() => vi.unstubAllGlobals());

describe("copyText", () => {
  it("copies via the native clipboard when available", async () => {
    const writeText = vi.fn().mockResolvedValue(undefined);
    vi.stubGlobal("navigator", { clipboard: { writeText } });
    await expect(copyText("Prompt output")).resolves.toBe("copied");
    expect(writeText).toHaveBeenCalledWith("Prompt output");
  });

  it("reports unavailable when neither clipboard method can run", async () => {
    vi.stubGlobal("navigator", {});
    await expect(copyText("Prompt output")).resolves.toBe("unavailable");
  });
});

export type CopyTextResult = "copied" | "unavailable";

export async function copyText(value: string): Promise<CopyTextResult> {
  if (typeof navigator !== "undefined" && typeof navigator.clipboard?.writeText === "function") {
    try { await navigator.clipboard.writeText(value); return "copied"; } catch { /* try the browser fallback */ }
  }
  if (typeof document !== "undefined" && typeof document.execCommand === "function") {
    const textArea = document.createElement("textarea");
    textArea.value = value;
    textArea.setAttribute("readonly", "");
    textArea.style.position = "fixed";
    textArea.style.opacity = "0";
    document.body.appendChild(textArea);
    textArea.select();
    const copied = document.execCommand("copy");
    textArea.remove();
    return copied ? "copied" : "unavailable";
  }
  return "unavailable";
}

import { afterEach, describe, expect, it, vi } from "vitest";
import { createScrollDepthTracker, trackGuideEvent } from "./guideAnalytics";

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("guide analytics", () => {
  it("uses stable, non-content event names", () => {
    const track = vi.fn();
    vi.stubGlobal("window", { umami: { track } });
    expect(trackGuideEvent("guide_interactive_copy", { guide_path: "/guides/promptforge-workflow-case-study" })).toBe(true);
    expect(track).toHaveBeenCalledWith("guide_interactive_copy", { guide_path: "/guides/promptforge-workflow-case-study" });
  });

  it("records each scroll milestone once", () => {
    const track = vi.fn();
    vi.stubGlobal("window", { umami: { track }, innerHeight: 1000, scrollY: 500 });
    vi.stubGlobal("document", { documentElement: { scrollHeight: 2000 } });
    const onScroll = createScrollDepthTracker("/guides/prompt-engineering-basics");
    onScroll();
    onScroll();
    expect(track).toHaveBeenCalledTimes(2);
    expect(track).toHaveBeenNthCalledWith(1, "guide_scroll_depth", { guide_path: "/guides/prompt-engineering-basics", depth_percent: 25 });
    expect(track).toHaveBeenNthCalledWith(2, "guide_scroll_depth", { guide_path: "/guides/prompt-engineering-basics", depth_percent: 50 });
  });
});

export type GuideAnalyticsEvent = "guide_scroll_depth" | "guide_interactive_view" | "guide_interactive_copy" | "guide_share";

type Umami = { track?: (event: string, data?: Record<string, string | number>) => void };

declare global {
  interface Window { umami?: Umami; }
}

export function trackGuideEvent(event: GuideAnalyticsEvent, data: Record<string, string | number> = {}) {
  if (typeof window === "undefined") return false;
  window.umami?.track?.(event, data);
  return true;
}

export function createScrollDepthTracker(guidePath: string) {
  const milestones = [25, 50, 75, 90];
  const seen = new Set<number>();
  return () => {
    if (typeof window === "undefined" || typeof document === "undefined") return;
    const scrollable = document.documentElement.scrollHeight - window.innerHeight;
    if (scrollable <= 0) return;
    const depth = Math.min(100, Math.round((window.scrollY / scrollable) * 100));
    for (const milestone of milestones) {
      if (depth >= milestone && !seen.has(milestone)) {
        seen.add(milestone);
        trackGuideEvent("guide_scroll_depth", { guide_path: guidePath, depth_percent: milestone });
      }
    }
  };
}

