 type AuthMode = "signin" | "signup" | "forgot" | "reset";

export default function Auth() {
  const [, navigate] = useLocation();
  const { user, loading: sessionLoading, signIn, signUp, signInWithGoogle, signInWithGitHub, sendMagicLink, sendPasswordReset, updatePassword, providers } = useSupabaseAuth();
  const [mode, setMode] = useState<AuthMode>("signin");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  useEffect(() => { if (!sessionLoading && user && !window.location.hash.includes("type=recovery")) navigate("/"); if (window.location.hash.includes("type=recovery") || window.location.hash.includes("access_token=")) setMode("reset"); }, [sessionLoading, user, navigate]);

  const clearMessages = () => { setError(""); setSuccess(""); };
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); clearMessages();
    if (mode !== "reset" && !email.trim()) { setError("Enter the email you use for your workshop account."); return; }
    if (mode !== "forgot" && password.length < 6) { setError("Use a password with at least 6 characters."); return; }
    setBusy(mode);
    const result = mode === "signin" ? await signIn(email, password) : mode === "signup" ? await signUp(email, password, displayName) : mode === "forgot" ? await sendPasswordReset(email) : await updatePassword(password);
    setBusy("");
    if (result.error) setError(result.error);
    else if (mode === "signup" && (result as { needsVerification?: boolean }).needsVerification) setSuccess("Account created. Check your inbox to verify your email, then sign in.");
    else if (mode === "forgot") setSuccess("Recovery instructions are on their way. Check your inbox.");
    else if (mode === "reset") { setSuccess("Password updated. Your workshop is secure again."); window.history.replaceState({}, "", "/auth"); setMode("signin"); }
    else { toast.success("Welcome back to the workshop"); navigate("/"); }
  };
  const social = async (provider: "google" | "github") => { clearMessages(); setBusy(provider); const result = provider === "google" ? await signInWithGoogle() : await signInWithGitHub(); setBusy(""); if (result.error) setError(result.error); };
