ader2 className="spin" size={16}/> : <span className="google-g">G</span>} {providers.google ? "Continue with Google" : "Google unavailable"}</button><button className="social-button" onClick={() => void social("github")} disabled={!!busy || !providers.github} title={!providers.github ? "GitHub is not enabled in Supabase" : undefined}>{busy === "github" ? <Loader2 className="spin" size={16}/> : <Github size={16}/>} {providers.github ? "GitHub" : "GitHub unavailable"}</button></div></>} {mode !== "forgot" && mode !== "reset" && <div className="auth-divider"><span>or use your email</span></div>}<form className="auth-form" onSubmit={submit}>{mode === "signup" && <label className="field"><span>Display name <small>optional</small></span><div className="input-with-icon"><UserRound size={15}/><input value={displayName} onChange={e => setDisplayName(e.target.value)} placeholder="How should we call you?" autoComplete="name"/></div></label>}{mode !== "reset" && <label className="field"><span>Email address</span><div className="input-with-icon"><Mail size={15}/><input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="you@example.com" autoComplete="email" required/></div></label>}{mode !== "forgot" && <label className="field"><span>Password {mode === "signup" && <small>6+ characters</small>}</span><div className="input-with-icon"><KeyRound size={15}/><input type={showPassword ? "text" : "password"} value={password} onChange={e => setPassword(e.target.value)} placeholder="Your password" autoComplete={mode === "signup" ? "new-password" : "current-password"} required/><button type="button" className="eye" onClick={() => setShowPassword(!showPassword)} aria-label={showPassword ? "Hide password" : "Show password"}>{showPassword ? <EyeOff size={15}/> : <Eye size={15}/>}</button></div></label>}{error && <div className="auth-message error" role="alert">{error}</div>}{success && <div className="auth-message success" role="status"><Check size={15}/>{success}</div>}<button className="forge-button auth-submit" type="submit" disabled={!!busy}>{busy === mode ? <Loader2 className="spin" size={16}/> : mode === "signin" ? <ArrowRight size={16}/> : mode === "signup" ? <UserRound size={16}/> : <KeyRound size={16}/>} {mode === "signin" ? "Sign in" : mode === "signup" ? "Create account" : mode === "reset" ? "Update password" : "Send recovery email"}</button></form>{mode === "signin" && <div className="auth-helpers"><button onClick={() => { clearMessages(); setMode("forgot"); }}>Forgot password?</button><button onClick={() => { clearMessages(); setMode("signup"); }}>Create account</button></div>}{mode === "signup" && <div className="auth-helpers single"><button onClick={() => { clearMessages(); setMode("signin"); }}>Already have an account? Sign in</button></div>}{(mode === "forgot" || mode === "reset") && <div className="auth-helpers single"><button onClick={() => { clearMessages(); setMode("signin"); }}>Back to sign in</button></div>}{mode !== "forgot" && mode !== "reset" && <><div className="magic-row"><button onClick={() => void magic()} disabled={!!busy}><Link2 size={15}/> Send me a magic link {busy === "magic" && <Loader2 className="spin" size={14}/>}</button></div><div className="guest-row"><Link href="/">Continue as guest <ArrowRight size={14}/></Link></div></>}{mode === "reset" && <p className="reset-note">Choose a new password with at least 6 characters. This link is single-use.</p>}<div className="auth-footnote"><ShieldCheck size={14}/> Secure account access.</div></section></main>;
