export type AssistantTarget = "chatgpt" | "gemini" | "claude";

export const getAssistantLaunchUrl = (target: AssistantTarget, prompt: string) => {
  const encoded = encodeURIComponent(prompt);
  if (target === "chatgpt") return `https://chatgpt.com/?q=${encoded}`;
  if (target === "gemini") return `https://gemini.google.com/app?prompt=${encoded}`;
  return `https://claude.ai/new?q=${encoded}`;
};

const assistantLabel = (target: AssistantTarget) => target === "chatgpt" ? "ChatGPT" : target === "gemini" ? "Gemini" : "Claude";

export const downloadPrompt = (prompt: string, format: "md" | "json" | "txt") => {
  const content = format === "json" ? JSON.stringify({ prompt }, null, 2) : format === "md" ? `# PromptForge prompt\n\n${prompt}\n` : prompt;
  const blob = new Blob([content], { type: format === "json" ? "application/json" : "text/plain" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `promptforge-prompt.${format}`;
  anchor.click();
  URL.revokeObjectURL(url);
  toast.success(`Exported ${format.toUpperCase()}`, { description: "Your prompt file is ready." });
};

